const variant=document.body.dataset.study;
const title={field:'A low flight',paper:'Shadows on a page',glass:'Two sides of the glass'}[variant];
const subtitle={field:'The mouse notices, waits, then follows. The butterfly comes within reach and lifts away.',paper:'Their shadows meet before their bodies do. A small encounter inside the writing.',glass:'They approach the same point from opposite sides. Close, but unable to touch.'}[variant];
const mouse=`<g id="mouse-art" fill="#a6b1a5"><path d="M30 47C17 52 14 39 4 44" fill="none" stroke="#a6b1a5" stroke-width="1.1" stroke-linecap="round"/><path d="M26 42C25 31 32 24 42 24C52 24 58 29 60 35Q67 35 71 42L65 46Q58 50 45 50C34 51 27 48 26 42Z"/><path d="M54 36C49 33 50 25 55 25C61 25 62 32 58 36"/><path d="M40 49 36 51 43 51M59 47 62 49 66 49" fill="none" stroke="#a6b1a5" stroke-width="1"/></g>`;
const butterfly=`<g id="butterfly-art"><g id="wings" fill="#7f9ca7" stroke="#b5c9ca" stroke-width=".3"><path d="M0 2C-18-20-29-18-22-2C-18 7-10 11 0 5Z"/><path d="M0 4C-14 8-19 15-12 18C-4 20-1 11 0 4Z"/><path d="M0 2C18-20 29-18 22-2C18 7 10 11 0 5Z"/><path d="M0 4C14 8 19 15 12 18C4 20 1 11 0 4Z"/></g><path d="M0-4 0 13M0-3-4-8M0-3 4-8" fill="none" stroke="#809b9a" stroke-width="1.3"/></g>`;
const stage=document.querySelector('.stage');
stage.innerHTML=`<div class="description"><h1>${title}</h1><p>${subtitle}</p></div><svg viewBox="0 0 1200 610" preserveAspectRatio="xMidYMid meet" aria-label="${title}"><defs><radialGradient id="fade"><stop stop-color="white"/><stop offset=".5" stop-color="white"/><stop offset="1" stop-color="black"/></radialGradient><mask id="oval"><ellipse cx="595" cy="370" rx="510" ry="260" fill="url(#fade)"/></mask><filter id="soft"><feGaussianBlur stdDeviation=".7"/></filter><filter id="shadow"><feGaussianBlur stdDeviation="2.5"/></filter></defs><g mask="url(#oval)"><path d="M0 440Q600 415 1200 438" stroke="#7b8b7833" fill="none"/><g id="cradle" fill="none" stroke="#889b8e" stroke-width="2" opacity=".22"><path d="M310 331Q380 358 450 331M319 329 329 365M439 329 430 365M321 375Q381 402 439 375"/></g><g id="field" stroke="#90a08c" opacity=".1">${Array.from({length:15},(_,i)=>`<path d="M${200+i*55} 430l${(i-7)*30} 120"/>`).join('')}</g><g id="page" fill="none" stroke="#9aa890" opacity=".16"><path d="M200 470 290 275Q455 248 600 294Q790 240 955 273L1030 470Q780 426 600 475Q380 430 200 470Z"/><path d="M600 294v181"/></g><g id="pane" stroke="#8aaba1" opacity=".18"><path d="M610 182 626 490"/><path d="M616 181 632 490" stroke-opacity=".3"/></g><g id="cat" fill="#849184" opacity=".12"><path d="M238 438Q218 428 224 415Q229 407 231 417Q229 426 243 427Q240 400 255 381L255 363 266 373 274 365 278 387Q292 410 279 438Z"/></g></g><g id="shadow-butterfly" filter="url(#shadow)" opacity=".12">${butterfly.replaceAll('id="','id="shadow-')}</g><g id="shadow-mouse" filter="url(#shadow)" opacity=".14">${mouse.replaceAll('id="','id="shadow-')}</g><g id="butterfly" opacity=".62" filter="url(#soft)">${butterfly}</g><g id="mouse" opacity=".58" filter="url(#soft)">${mouse}</g><text id="poem" x="600" y="180" fill="#d6ddd4" text-anchor="middle" font-family="Georgia,serif" font-size="25"><tspan x="600">The present becoming the past</tspan><tspan x="600" dy="40">colours all my fears.</tspan></text></svg>`;
const $=s=>document.getElementById(s),slider=document.querySelector('input'),play=document.querySelector('[data-action=play]');
const ease=t=>{t=Math.max(0,Math.min(1,t));return t*t*(3-2*t)},mix=(a,b,t)=>a+(b-a)*t;
const points=variant==='field'?[[120,260],[420,290],[630,416],[660,395],[910,230],[1110,150]]:variant==='paper'?[[200,250],[430,310],[590,397],[625,388],[900,250],[1050,180]]:[[950,230],[750,310],[646,420],[646,420],[780,300],[1030,180]];
let time=0,running=!matchMedia('(prefers-reduced-motion: reduce)').matches,last=0,raf;
function draw(){const p=time/36,k=Math.min(4,Math.floor(p*5)),t=ease(p*5-k);const bx=mix(points[k][0],points[k+1][0],t),by=mix(points[k][1],points[k+1][1],t)+Math.sin(time*1.2)*3;
 const meet=ease((p-.22)/.22),leave=ease((p-.62)/.28);let mx=variant==='glass'?mix(370,585,meet):mix(390,variant==='paper'?562:590,meet);mx+=variant==='glass'?0:leave*160;
 const reach=Math.max(0,1-Math.abs(p-.51)/.12),my=(variant==='paper'?414:431)-reach*(variant==='glass'?5:12);const turn=variant==='glass'?1:p>.7?1:1;
 $('butterfly').setAttribute('transform',`translate(${bx} ${by}) rotate(${Math.sin(time*.8)*7})`);
 const fold=.26+.74*(.5+.5*Math.sin(time*9));$('wings').setAttribute('transform',`scale(${fold} 1)`);
 $('mouse').setAttribute('transform',`translate(${mx-50} ${my-30}) scale(.82) rotate(${-reach*9} 60 45)`);
 $('shadow-butterfly').setAttribute('transform',`translate(${bx} ${variant==='paper'?425:447}) scale(.8 .13)`);
 $('shadow-mouse').setAttribute('transform',`translate(${mx-42} ${variant==='paper'?438:447}) scale(.8 .12)`);
 $('cradle').style.opacity=variant==='field'?String(.27*(1-ease((p-.1)/.5))):'0';$('field').style.opacity=variant==='field'?String(.12*ease(p/.5)):'0';$('page').style.opacity=variant==='paper'?'.22':'0';$('pane').style.opacity=variant==='glass'?'.35':'0';$('cat').style.opacity=variant==='field'?'.11':'0';
 $('poem').style.opacity=variant==='paper'?'.7':'0';$('butterfly').style.opacity=String(.6*Math.min(1,p/.08,(1-p)/.1));$('mouse').style.opacity=String(.38*ease(p/.12));slider.value=time;
}
function tick(now){if(last)time+=(now-last)/1000;last=now;if(time>36){time=36;running=false}draw();if(running)raf=requestAnimationFrame(tick);else{last=0;play.textContent='Play';play.setAttribute('aria-pressed','false')}}
function pause(){running=false;cancelAnimationFrame(raf);last=0;play.textContent='Play';play.setAttribute('aria-pressed','false')}
play.addEventListener('click',()=>{if(running){pause();return}if(time>=36)time=0;running=true;play.textContent='Pause';play.setAttribute('aria-pressed','true');raf=requestAnimationFrame(tick)});
document.querySelector('[data-action=replay]').addEventListener('click',()=>{pause();time=0;draw();running=true;play.textContent='Pause';play.setAttribute('aria-pressed','true');raf=requestAnimationFrame(tick)});
slider.addEventListener('input',()=>{pause();time=Number(slider.value);draw()});document.addEventListener('visibilitychange',()=>{last=0});draw();if(running){play.textContent='Pause';play.setAttribute('aria-pressed','true');raf=requestAnimationFrame(tick)}
